const POS = ['rally','surge','bullish','gains','gain','rises','rise','soar','jump','record','high','recover','boom','growth','profit','strong','positive','breakout','upgrade','buy','hawkish','stimulus','approval','inflow','etf'];
const NEG = ['crash','drop','bearish','loss','fall','plunge','sink','decline','fear','warn','sell','downgrade','weak','negative','slump','tumble','panic','collapse','recession','hack','lawsuit','outflow','ban'];
const SYMBOLS = [
  {sym:'BTCUSDT', keys:['bitcoin','btc']},
  {sym:'ETHUSDT', keys:['ethereum','eth']},
  {sym:'SOLUSDT', keys:['solana','sol']},
  {sym:'XRPUSDT', keys:['ripple','xrp']},
];

function scoreText(t) {
  const w = String(t || '').toLowerCase().split(/[^a-z0-9]+/).filter(Boolean);
  let p = 0, n = 0;
  for (const x of w) {
    if (POS.includes(x)) p++;
    if (NEG.includes(x)) n++;
  }
  const tot = p + n;
  if (!tot) return {sentiment_score: 0, impact_score: 0.25};
  const s = (p - n) / tot;
  const impact = Math.min(1, 0.2 + tot / 12);
  return {
    sentiment_score: Math.round(Math.max(-1, Math.min(1, s)) * 1000) / 1000,
    impact_score: Math.round(impact * 1000) / 1000,
  };
}

function collectArticles(j) {
  const root = j.json || j.result || j.data || j;
  const candidates = [];
  const push = (arr) => {
    if (!Array.isArray(arr)) return;
    for (const a of arr) {
      if (!a) continue;
      if (typeof a === 'string') candidates.push({title: a, summary: ''});
      else if (typeof a === 'object') candidates.push(a);
    }
  };
  if (!root || typeof root !== 'object') return candidates;
  push(root.articles); push(root.results); push(root.items); push(root.headlines);
  if (root.data) { push(root.data.articles); push(root.data.results); }
  if (typeof root === 'object' && (root.title || root.headline)) candidates.push(root);
  // raw string content with JSON blob
  for (const key of ['content','answer','text','output','result']) {
    if (typeof root[key] === 'string') {
      try {
        const t = root[key].replace(/^```json\s*/i,'').replace(/```$/i,'').trim();
        const si=t.indexOf('{'); const ei=t.lastIndexOf('}');
        if (si>-1 && ei>si) {
          const parsed=JSON.parse(t.slice(si,ei+1));
          push(parsed.articles); push(parsed.results);
        }
      } catch (e) {}
    }
  }
  return candidates;
}

function extractHits(j) {
  const hits=[]; const pools=[];
  if (!j || typeof j !== 'object') return hits;
  if (Array.isArray(j.results)) pools.push(j.results);
  if (Array.isArray(j.data)) pools.push(j.data);
  if (j.data && Array.isArray(j.data.results)) pools.push(j.data.results);
  if (Array.isArray(j.organic)) pools.push(j.organic);
  if (Array.isArray(j.news_results)) pools.push(j.news_results);
  if (Array.isArray(j.items)) pools.push(j.items);
  for (const arr of pools) {
    for (const r of arr) {
      if (!r || typeof r !== 'object') continue;
      hits.push({
        title: String(r.title||r.name||'').trim(),
        summary: String(r.snippet||r.description||r.content||'').trim().slice(0,280),
        url: String(r.url||r.link||r.href||'').trim(),
        source: 'qt-search',
      });
    }
  }
  return hits;
}

function safe(name){ try { return $(name).all().map(i=>i.json); } catch(e) { return []; } }
function safeOne(name){ try { return $(name).first().json||{}; } catch(e) { return {}; } }

const out = [];
const seen = new Set();

// Path A: ScrapeGraphAI extracts (may be multiple homepage items)
for (const j of safe('ScrapeGraphAI Extract')) {
  const source = j.source || 'scrapegraph';
  for (const a of collectArticles(j)) {
    const title = String(a.title || a.headline || '').trim();
    if (!title) continue;
    const summary = String(a.summary || a.description || a.snippet || '').trim();
    const text = `${title} ${summary}`;
    const key = title.toLowerCase();
    if (seen.has(key)) continue; seen.add(key);
    const scores = scoreText(text);
    let symbols = [];
    if (Array.isArray(a.assets)) symbols = a.assets.map(s => String(s).toUpperCase().replace(/USDT$/, '') + (String(s).toUpperCase().endsWith('USDT')?'':''));
    // normalize to QT symbols
    const found = [];
    const low = text.toLowerCase();
    for (const s of SYMBOLS) {
      if (s.keys.some(k => low.includes(k))) found.push(s.sym);
    }
    if (!found.length) found.push('BTCUSDT');
    for (const sym of found) {
      out.push({ json: {
        symbol: sym,
        headline: title,
        summary,
        url: a.url || a.link || '',
        source,
        sentiment_score: scores.sentiment_score,
        impact_score: scores.impact_score,
        provider: 'scrapegraphai+qt14',
      }});
    }
  }
}

// Path B: QT search headlines
for (const name of ['Tavily Search QT','SerpAPI News QT','Jina Search QT','Firecrawl Direct QT']) {
  for (const h of extractHits(safeOne(name))) {
    const title = h.title; if (!title) continue;
    const key = title.toLowerCase();
    if (seen.has(key)) continue; seen.add(key);
    const scores = scoreText(`${title} ${h.summary}`);
    const low = `${title} ${h.summary}`.toLowerCase();
    const found = [];
    for (const s of SYMBOLS) {
      if (s.keys.some(k => low.includes(k))) found.push(s.sym);
    }
    if (!found.length) found.push('BTCUSDT');
    for (const sym of found) {
      out.push({ json: {
        symbol: sym,
        headline: title,
        summary: h.summary,
        url: h.url,
        source: name,
        sentiment_score: scores.sentiment_score,
        impact_score: scores.impact_score,
        provider: 'qt-search+14',
      }});
    }
  }
}

// optional CMC context on first row
try {
  const cmc = safeOne('CMC Quotes QT');
  const d = cmc.data || cmc;
  const market = {};
  for (const sym of ['BTC','ETH','SOL']) {
    const row = d[sym]; if (!row) continue;
    const q = (row.quote && row.quote.USD) || {};
    market[sym] = { price: q.price, change_24h: q.percent_change_24h };
  }
  if (out.length && Object.keys(market).length) out[0].json.market = market;
} catch (e) {}

if (!out.length) {
  return [{ json: { symbol:'BTCUSDT', headline:'', summary:'', skip:true, provider:'qt14-empty' } }];
}
return out.slice(0, 40);
